-// Duration parsing for the agent test. Implement parseDuration.
-//
-// parseDuration(text) -> number of seconds (integer)
-// Units: h (hours), m (minutes), s (seconds). Units may appear in any order once each,
-// with optional whitespace between parts: "1h30m", "90s", "2h 5s", "45m".
-// A bare number means seconds: "120" -> 120.
-// Throw a TypeError when text is not a string.
-// Throw a RangeError for anything else that is not a valid duration:
-// empty string, unknown unit, a repeated unit, a negative or fractional number.
+export function parseDuration(text) {
+  if (typeof text !== 'string') {
+    throw new TypeError('text must be a string');
+  }

-export function parseDuration(text) {
-  throw new Error('not implemented');
+  // Empty or whitespace-only string should throw RangeError
+  if (text.length === 0 || text.trim() === '') {
+    throw new RangeError('Invalid input');
+  }
+
+  const units = {
+    h: 3600,
+    m: 60,
+    s: 1
+  };
+
+  const validUnits = new Set(['h', 'm', 's']);
+  const seen = new Set();
+
+  // Split by whitespace but keep empty strings for bare numbers
+  const parts = text.split(/\s+/);
+
+  let total = 0;
+
+  for (const part of parts) {
+    if (part === '') {
+      continue;
+    }
+
+    // Check if it's a bare number (no unit)
+    if (!/[hms]$/.test(part)) {
+      // It's a bare number
+      const num = parseInt(part, 10);
+      if (isNaN(num) || !Number.isInteger(num)) {
+        throw new RangeError('Invalid number');
+      }
+      if (num < 0 || num > 999999999) {
+        throw new RangeError('Number out of range');
+      }
+      total += num;
+      continue;
+    }
+
+    // Split part into number and unit parts (e.g., '1h30m' -> ['1', 'h', '30', 'm'])
+    const segments = part.split(/([hms])/);
+    
+    for (let i = 1; i < segments.length; i += 2) {
+      const unit = segments[i];
+      const valueStr = segments[i - 1];
+      
+      if (!validUnits.has(unit)) {
+        throw new RangeError(`Unknown unit: ${unit}`);
+      }
+      
+      if (seen.has(unit)) {
+        throw new RangeError(`Repeated unit: ${unit}`);
+      }
+      seen.add(unit);
+      
+      const value = parseInt(valueStr, 10);
+      if (isNaN(value) || !Number.isInteger(value)) {
+        throw new RangeError('Invalid number');
+      }
+      if (value < 0 || value > 999999999) {
+        throw new RangeError('Number out of range');
+      }
+      
+      total += value * units[unit];
+    }
+  }
+
+  return total;
 }

